/* 令和5年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r05.committeeSessions.push(...[{"id":"r05-20231129-14","meetingId":"r05-cm11","date":"2023年11月29日","dateIso":"2023-11-29","committee":"行財政改革特別委員会","time":"午前１０時００分～午前１１時５１分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"山本委員","kind":"提案","question":"今、お聞きして、とてもいい進め方をしていただいていると感じました。策定委員会から提案された、多様な人々が集い・学び・助け合い・心と体の健康を育む交流拠点というコンセプトがとてもいいなと思いました。区民の皆様の意見をお聞きするというすごく大事なことだと考えていますが、このパブリックコメントを１２月に実施した後、このコメントはどのように答申などに反映されるのでしょうかです。","respondent":"吉岡政策推進担当課長","answer":"スケジュールに関しましてですけれども、１２月にパブリックコメントをやらせていただいて、その後皆さんからしっかりしたご意見をいただきながら、まず、これが反映に資するかどうかというところも委員会のほうできちんと検討させていただいて。","voiceIndex":5,"id":"exchange-001"},{"speaker":"山本委員","kind":"質問・要望","question":"ご回答ありがとうあります。どういった施設かというところで具体的な施設を上げるということではなく、こういった施設があったらいいという考え方で、こういったプロセスから結論に至ったということで理解いたしました。よいなと思いました。こういった広い場所ということで、これは全て入るように、ぜひ進めていただきたいなと考えています。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"特にアール・ブリュットの展示とかこういったことも明確に書かれているということで、あとは障害のある方の就労であるとか、そういったことも書かれているということで、非常にすばらしいなと思ったのですけれども、今回のメインコンセプトである図書のことについてまずお伺いをしたいのですが、素案のほうを拝見いたしますと、素案の１７ページ。１９ページには図書館機能というふうに書いてあるのです。","respondent":"吉岡政策推進担当課長","answer":"１９ページの図書館機能というところで入れさせていただいたのですけれども、図書館というのが、そういう施設というような位置づけで言葉を、一旦こういった使い分けをさせていただいているのですが、今回パブリックコメントも経まして。","voiceIndex":9,"id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問","question":"障害とか。それは何か指定管理のようなものをして、指定管理者が全部を見るという形なのか、それとも図書館機能というところでそれは教育委員会があくまで責任を持ってそこはやりますよというところなのか、司書の配置をどうするのかとか、いろいろな話が出てくると思うのですが、その辺りはどのようなお考えなのか、現在のところ、決まっていることを教えてください。","respondent":"吉岡政策推進担当課長","answer":"委員おっしゃるとおり、この施設、かなり多岐にわたる複合施設という形になりますので、運用形態につきましては、次年度、計画の策定を進める中で検討していく形にはなりますけれども、できる限り民間の活力も活用しながら運営していくべきだというふうに捉えているところです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"それと、そういうふうになってくると、多岐にわたる、スポーツも入っている、いわゆる障害も入っている、防災も入っているというところで、品川区にあまり例を見ないような複合施設になってくるのかなと思うのですけれども、こういうところに関しては、これから何か検討していくというのはもうここで素案が出たというところで、策定委員会の役目を終わって。","respondent":"吉岡政策推進担当課長","answer":"こちらにつきまして、策定委員会のほうもこういった類似の施設を例に出しながら、委員の皆様にもご覧いただいて、こういう感じだねというような認識を、感想をいただいたです。","voiceIndex":13,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問","question":"先ほどできるだけ民間の活用をされていきたいというご答弁があったのですけれども、これから先はもう庁内でどんどん進んでいくということになるのですか。もう一つ言ってしまえば、その途中で議会への報告があるのかどうかというところも含めて、我々が何か意見を言える場があるのかということも含めて質問させていただきました。もう一度お願いします。","respondent":"吉岡政策推進担当課長","answer":"大変失礼いたしました。今年度は多くの方、区民の方、あるいは地域の方に入っていただく委員会という形式で行いましたけれども、次年度はどちらかというと、庁内の検討会議というのも多く重ねる予定です。","voiceIndex":15,"id":"exchange-006"},{"speaker":"えのした委員","kind":"質問","question":"ご説明ありがとうございました。複合施設、多岐にわたる取組で、私も拝見させていただきましたが、できるのかなと思いながらも、敷地面積が８,４７２.６９m2ですか。パブリックコメントの実施。オープンハウス方式の開催の日にちが１２月８日・９日・１４日の３日間出ていますが、これは、どちらの場所でやるのかというのが示されてないので、そこをお伺いさせていただけますでしょうか。","respondent":"吉岡政策推進担当課長","answer":"オープンハウス型の説明会の実施場所ですけれども、旧荏原第四中学校の集会室のほうで、３日間行わせていただきます。","voiceIndex":18,"id":"exchange-007"},{"speaker":"えのした委員","kind":"質問・要望","question":"本当に１２月、もう年末１か月の中で、パブリックコメント、なかなか皆さん区民の方もお忙しいと思うのですけれども、本当に多くのお声を頂戴して、私も先日の一般質問でも質問させていただきましたが、様々な交流によって災害時の助け合いの輪が広がるという他の自治体の取組なども随分入っていますので、単に避難場所というものではなくて、防災の拠点となるような施設になっていくように、今後も期待して。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"コンセプト案が薄く、どこにでもある施設になるのではないか。それと、これまで私たち共産党は特別養護老人ホームなどの増設もここに求めてきましたけれども、素案の１０ページのところでも、世論調査、荏原東地区では、区内全域よりも福祉保健施設の要望が強い結果が示されていると思いました。特別養護老人ホームも導入施設に入れていただきたいなと思うのですけれども、いかがでしょうか。","respondent":"吉岡政策推進担当課長","answer":"こういったものを中心に据えながらやっていこうというところで、第３回の策定委員会のほうでは、こちらのほうで進めるというようなお話をいただいたところです。先ほど、特別養護老人ホームというお話がございました。","voiceIndex":22,"id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"要望です。私たちも説明会を要望してきましたけれども、区としては、説明会を実施しないというような姿勢だったのではないかと思うのですが、これは何か方針が変わったのか要望があったか伺いたいのと、住民同士がどういう要望をみんなが持っていて、お互いに知り合うという上では教室型の説明会も重要だと思い、これも実施していただきたいなと思うのですが、いかがでしょうか。","respondent":"吉岡政策推進担当課長","answer":"今回この旧荏原第四中学校、非常に大きい施設になります。今回、方針の素案のところでも、複合型施設ですので、こういった新たな試みとして、こちらの施設については、オープン型で説明会を実施したいと考えたところです。","voiceIndex":24,"id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"意見","question":"分かりました。どちらにしても区民の意見をさらに聞いていただいて、本当に充実する、愛される施設になっていくといいなというところでは私たちも一緒に意見を上げていきたいなというふうに思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":26,"id":"exchange-011"},{"speaker":"松本委員","kind":"質問","question":"そうすると、例えば二葉のほうは設立が１９７０年で、ゆたか図書館は１９７５年ということなので、場合によっては、この辺り将来的には統合ということも、一応視野には入れていらっしゃるということなのでしょうか。","respondent":"吉岡政策推進担当課長","answer":"これからの図書館の計画、整備計画、あるいは修繕計画。そういったところも含めまして、今回の旧荏原第四中学校のところの図書機能、図書館機能、図書スペース。こういったものがどれだけ拡充できるかといったところで、そういった話になってくるかと考えています。","voiceIndex":30,"id":"exchange-012"},{"speaker":"松本委員","kind":"質問・要望","question":"分かりました。最後は要望ですけれども、これだけ複合的な施設ですので、ぜひ公民連携といいますか、ＰＰＰ、ＰＦＩの視点は取り入れて、整備を進めていただきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-013"},{"speaker":"まつざわ委員","kind":"質問","question":"会派からも、例えばマイスクールに関しては、中心にあったほうがいいというのもしっかり反映されていて、非常に評価が高いところでありまして、私からは、まず１点伺いたいのは、防災拠点という部分で、もともと豊町三丁目、四丁目の避難所でありますけれども、入りきれないから、実際あそこの人たちは大崎高校に行ったりという、分散している。","respondent":"吉岡政策推進担当課長","answer":"しかしながら、今委員もご紹介のとおり、防災の拠点というところで、一番大きいところは、今、５７２人の区民避難所として指定されているところなのですけれども、最低でもここは確保してほしいというところが、地域の強い声だです。","voiceIndex":34,"id":"exchange-014"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"５７０名を入れるというのは重々承知で、絶対それはマストな感じになっているのですけれども、例えば少し要望として言わせていただきたいのは、前回の決算特別委員会でも言わせてもらったのですが、消防団というのはもう正式に言うと東京都の管轄なので、品川区がどうとかということは確かに全く筋違いというのは私も重々承知なのですが、例えばそういう団小屋というのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-015"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ご説明ありがとうございました。それぞれ行政需要の中で、４項目あって、戸越荏原地区にも複合拠点となり得る施設になるのではないかなと考えています。本当に地域の皆さんの一番の要望は、私は防災の拠点だと思っているのです。例えば備蓄倉庫とかいろいろ書いてありますけれども、具体的に絶対これは必要というような何か意見、どういった意見があったのかというのを、まず教えていただきたいと思います。","respondent":"吉岡政策推進担当課長","answer":"どういった意見があったかですけれども、今回方針というところで、非常に大きいところでお話し合っていただくといったところで、特に備蓄倉庫とかあまり細かい機能についてのお話はなかったところですが、体育館ですとかこういう教室系のスペース。","voiceIndex":40,"id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ありがとうございました。ぜひ、これからパブリックコメントがあって、それぞれまた区民の要望、意見があると思いますので、おまとめいただいて、進めていただきたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-017"},{"speaker":"塚本委員","kind":"質問","question":"質問なのですけれども、学びの場と同時ににぎわい・交流というところも入ってきているわけで、どちらかというと図書館というのは静かなイメージで、学びというとみんなで集団でいろいろ学習するというのもあるのかもしれないですが、基本的には静かな感じがイメージとしてあるのですが、そういった中でのにぎわいとか交流というのをどういうふうに織り交ぜていくのかというところについて、お伺いしたい。","respondent":"吉岡政策推進担当課長","answer":"委員の皆様から、視察先でご提案があったところも含めまして、先行事例を今後研究していきまして、こういったものをまとめていきたいというふうに考えてあります。","voiceIndex":46,"id":"exchange-018"},{"speaker":"塚本委員","kind":"提案","question":"別の観点なのですけれども、屋上緑化とは別にビオトープが出ていて、ビオトープはこれまでも例えば戸越公園に蛍を何とかみたいなことで、ビオトープを造れないかとか、いろいろなお話が地域でもあったりしたのですが、実際に生態系を人工的に維持していくのが非常に大変というふうなことで、そういったところでの実現性とか現実性というのは、ある程度見越した上でここまで提案書には載せているのか。","respondent":"吉岡政策推進担当課長","answer":"こういった具体的な計画落としていく中で、適切に進められるよう、区のほうも努力していきたいと考えているところです。","voiceIndex":48,"id":"exchange-019"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、ビオトープということで言うと、生き物を飼うということも一応念頭に入っているのですか。","respondent":"吉岡政策推進担当課長","answer":"ビオトープにつきましては、直接そこまであまり深掘りをされていない部分です。こういった生き物が飼いたいだとか、そういった展示会をしたいとか、そこまでの議論は深まっていない部分ではありますので、こちらは今後検討していきたいというふうに考えてあります。","voiceIndex":50,"id":"exchange-020"},{"speaker":"塚本委員","kind":"意見","question":"今、いろいろな不登校対策というか不登校の児童生徒にどうやって対応していくかということでは、居場所みたいなそういうものもあって、必ずしも学校に戻すということを念頭にしないような形で、何とか子供たちを不登校から少しでも外に出ていくとか、少しでも社会になじんでいけるとか、学校に適応できるというようなことも対策としては考えられてきている流れもあるので。","respondent":"吉岡政策推進担当課長","answer":"そういった場を目指していきたいというふうに考えてあります。","voiceIndex":52,"id":"exchange-021"},{"speaker":"松永委員","kind":"質問","question":"先ほどまつざわ委員からありましたけれども、消防団の分団小屋というのも必要かとは思うのですが、今消防団の訓練場所というのがあまりなくて、今、文庫の森でやっているそうなのですが、ほかの分団は区役所の第二駐車場に来たりとか移動する部分があるので、もし人工芝であった場合というのは、可搬ポンプを使うことができるのかどうかというのと、土だったら多分できるとは思うのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-022"},{"speaker":"松永委員","kind":"質問","question":"いろいろな方が来られるということで、もう一つなのですけれども、まだ先の話になるのですが、東急大井町線、恐らく高架になると思うのですが、その辺のセットバックとかは関係が出てくるのかどうかというのをお知らせいただければと思います。すごく危ないので、何かそういった対策とかも含めて考えていただければと思うのですけれども、ご意見を伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"今、委員からのお話のとおり、四方に囲まれて非常に狭隘道路があります。高架下のところもありますので、今後基本計画の中で、人の流れ、交通の流れ。そういった部分も確認しながら基本計画の中で、安全にこの施設を使用していただけるように努めてまいるところです。","voiceIndex":58,"id":"exchange-023"},{"speaker":"せお副委員長","kind":"質問","question":"ご説明ありがとうございました。そして、様々議論伺っていました。でも地域バランスを考えると、今、マイスクール八潮があって、大井のほうにできると。もう１点インクルーシブひろばベルが暫定で移ってくると。なので、そういった２点、教育委員会であったり、あと障害福祉のほうとかとしっかり連携して話し合える、庁内検討できる場所というのが、今あるのかどうか、お聞きしたいです。","respondent":"吉岡政策推進担当課長","answer":"詳細につきましては、今後の検討になりますけれども、現時点でも必要な情報につきましては、各所管と連携を取っているというところだけ、お伝えさせていただければと思います。","voiceIndex":61,"id":"exchange-024"},{"speaker":"せお副委員長","kind":"意見","question":"ここの庁舎跡地もそうですし、しっかり区民の声とか地域のお声とかを聞いてくださっているので、そこももちろん大切ですし、ただ、区の計画のバランスとかそういったところも先ほどもお話がありましたけれども、同じようなものが同じ地域に２つあるとか３つあるとか、そういったことももったいないなということもあるので、ぜひそこら辺もこれから間に合うようでしたら、インクルーシブひろばベルに関しては。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"質問","question":"スライドの３ページ目、オンライン手続の拡大ということで示されていますけれども、これらはマイナンバーカード取得とセットになるのか、マイナンバーカードがなければ行政サービスが受けられないという仕組みにはすべきではないと思うのですけれども、伺いたいと思います。","respondent":"河西情報戦略担当課長","answer":"例えば、従来どおり免許証のコピーですとか、そういった本人確認するものを添付することによって受け付けるという方法も提供しておりますので、マイナンバーカードがないと利用できないかというと、そうではないということでご報告いたします。","voiceIndex":68,"id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"あらゆるデータを行政側に集積して、このビッグデータを企業に提供するなど、もうけの種になっていく、こうした匿名加工情報として提供されるという活用はすべきでないということはずっと言ってきているのですけれども、このマイナンバーカードの取得も任意というのが法の規定でありますので、ひもづけの間違いや情報の漏えいなど様々な問題も起こっていますので。","respondent":"河西情報戦略担当課長","answer":"ＤＸの流れについて、改めて認識を共有しますと、ＤＸに関しては、デジタルを業務に取り入れることによって、質の向上という側面が非常に強いと思っています。","voiceIndex":70,"id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"質が高くなるのはいいことなのですけれども、それとともにこれまではそういったＤＸを進めることで、要は手間が省ける職員の部分をしっかり区民サービスに活かしていくということをおっしゃっていただいていたので、その考えは今も変わらないということで、いいでしょうか。人員削減ありき、行政コスト削減ありきのデジタル化は、改めてやめるように求めたいと思うのですけれども、いかがでしょうか。","respondent":"河西情報戦略担当課長","answer":"委員おっしゃるとおり、ＤＸ推進基本方針には、まさに今おっしゃったとおり、ＤＸを進めることによって、空いた手間、稼働を本来必要な区民との対話ですとか、相談受付ですとか、そういった業務に振り向けることによって。","voiceIndex":72,"id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問","question":"スライドで言う１３のところです。テレワークについては、メリットもデメリットもあるのかなと思うのですけれども、この新テレワークの導入も示されていまして、テレワーク利用促進については、数値の目標というのがあるのかどうか。ぜひ、言いたいのは現場で働く方の希望や声を聞きながら、拡大ありきではなくて、実態や必要に応じて進めていくべきだと思うのですけれども、いかがでしょうか。","respondent":"河西情報戦略担当課長","answer":"もちろん今の業務がありますし、例えば窓口業務ですとかそういった業務がありますが、そういった中でもテレワークという仕組みを提供することによって、うまく職員が各所管のほうで工夫して利用できるように、環境を整えるという意味で、拡大のほうをしてまいります。","voiceIndex":74,"id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"分かりました。改めて、テレワークにおいては、推進ありきではなくて、仕事の実態や職員の要望に応じて進めるように求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-030"},{"speaker":"山本委員","kind":"質問・要望","question":"できそうかどうかというところについて、お伺いしたいと思います。新庁舎建設が予定されておりますので、そこへの関係というところで、どの程度お考えなのかというのをお聞かせいただきたいというのが２つ目になります。例えばそういった個人情報に関わるものは持ち帰れないとか、もしくは持ち帰った自宅の中では見られないとか、そういった対策などがおありでしたらぜひ伺いたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-031"},{"speaker":"山本委員","kind":"質問・要望","question":"１５ページのスライドでご説明いただいた、この業務のところでの情報漏えいのところですが、そのようなご検討をとお答えをされているということで理解をしたのですが、１点確認をさせていただきたいのが、区役所内で扱われる業務の中で、区民の方々の様々な個人情報を扱われるところがあると思うのですけれども、それがテレワークで自宅でも見られるような状況なのでしょうか。確認させてください。","respondent":"河西情報戦略担当課長","answer":"先ほどのご質問にお答えいたします。１５ページの図、左下を見ていただきたいと思います。品川区役所は、３つのネットワークで構成されております。マイナンバー系、ＬＧＷＡＮ系、インターネット系。今回、テレワークの対象とするのが、職員端末ＬＧＷＡＮ系の端末になります。","voiceIndex":82,"id":"exchange-032"},{"speaker":"山本委員","kind":"質問・要望","question":"これすごく大きなことだと思うのですけれども、実際使っていただく皆様にこういった情報の管理のところについてもしっかりと守っていただけるように、周知をお願いできればと思って、職員の皆様にご説明していただきたいです。そして、これを導入した後、ぜひ効果検証をしていただいて、多くの方々が利用できるようにしていただきたい、使いやすい仕組みにしていただきたいという、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-033"},{"speaker":"あくつ委員","kind":"確認","question":"先ほどからこれによって、個人情報等は自宅でテレワークであったとしても、マイナンバー系ということでその情報については扱わないというお話でしたけれども、今まで行政の方がタブレットであるとかＵＳＢとかを、例えば夜飲食の場に置き忘れてしまって紛失してしまったみたいなことが年に数回報告がありますが、例えばこの端末を持ち帰って、そのようなことが起きた場合。","respondent":"河西情報戦略担当課長","answer":"接続するときには、必ずモバイルネットワークＳＳＩＤというものを通して接続を行います。そのときのＳＳＩＤ認証というのを実施しております。この３つを合わせることで、知識と物がないと接続できないというところを担保して、セキュリティの確保を実施しております。","voiceIndex":86,"id":"exchange-034"},{"speaker":"あくつ委員","kind":"確認","question":"分かりやすくというところで、私の知識が浅薄なので、少し分からない部分もあったのですけれども、今おっしゃっていたような３つの認証があって、それは職員の頭の中にあるものであって、例えば端末は予約は要らないという話ですが、パスワードなどは紙で示されるというものなのか、それを例えば本人がメモ帳や手帳に貼り付けておいて、それと一緒になくしてしまった場合でも。","respondent":"河西情報戦略担当課長","answer":"認証を通してしまいますので。ですので、先ほどご説明したとおり、２要素認証という仕組みを使って、ＩＤパスワードプラス端末、あとモバイルルーター。この３つがセットでないと接続できないというところまでセキュリティの担保をしようというところになっております。","voiceIndex":88,"id":"exchange-035"},{"speaker":"あくつ委員","kind":"質問","question":"だんだん理解をしてきているのですが、モバイルルーターというのは、これは説明で多分あったのかもしれないのですけれども、モバイルルーターも一括して貸し出すということなのでしょうか。それはもう間違いないということなのですか。","respondent":"河西情報戦略担当課長","answer":"それを分かっている方であれば、接続できてしまう。ただし、そうなってしまうので、我々日頃からセキュリティに関する研修を実施しております。","voiceIndex":90,"id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問","question":"確率が少ないのは分かっているのですけれども、最後にすみません。私も素人考えなのですが、例えば本人認証のときに、今生体認証とありますよね。本人の顔とか網膜とか指紋とか。そういったものでの、それがなければ突破できないというような、そこまでは今回はつくらないということなのでしょうか。","respondent":"河西情報戦略担当課長","answer":"今、生体認証を使っていますが、そちらの認証サーバーというものが、庁内にあります。今回は外から接続しますので、その生体認証サーバーにアクセスできないところから接続をかけますので、生体認証は使うのが難しいという回答になりまして、ＩＤとパスワードにしています。","voiceIndex":92,"id":"exchange-037"},{"speaker":"あくつ委員","kind":"確認","question":"ありがとうございました。今、生体認証は難しいということでした。やれることはやってというところですので、端末を物理的になくしちゃう、ルーターを物理的になくしちゃうということは、これは人間だから起こり得る、起こってはいけないことですけれども、起こり得る可能性があるということですが、限りなく情報の流出は低いのだろうなというところで確認させてきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-038"},{"speaker":"えのした委員","kind":"質問","question":"品川区電子申請サービスの利用状況を見ても、訪問者数、申請数、順調に伸びているということで、１９時以降仕事が終わってからですかね。すごく助かっているのではないかなということは数字で感じ取れます。区民の方からアンケートを取っているか分かりませんけれども、チャットボットはすごく分かりやすいよとか使い勝手がよかったとか、何かそういうような声があれば教えていただけますでしょうか。","respondent":"河西情報戦略担当課長","answer":"今ちょうどＣｈａｔＧＰＴが出てきておりまして、いろいろなマニュアルを読み込んで、それに回答できるような仕組みというのが出てきておりますので、そういった仕組みを総合窓口として、ＡＩチャットボットに活用できないかというところも今ちょうど研究を進めておりますので。","voiceIndex":96,"id":"exchange-039"},{"speaker":"山本委員","kind":"質問","question":"２回目で恐縮ですが、１点追加でお聞かせください。これは一般質問でも申し上げたところなのですが、そういったセットでやるべき。シニアスマホ教室は高齢者地域支援課ですか。所管が別のところでやっていらっしゃるという。","respondent":"河西情報戦略担当課長","answer":"今の高齢者地域支援課のほうでシニア教室を実施しておりますが、そちらに関しては、どうしても教室数に限って言うと、なかなか大人数が参加できないので、ある地域のある特定の方に限られてしまうというのがどうしても課題としています。","voiceIndex":100,"id":"exchange-040"},{"speaker":"山本委員","kind":"質問・要望","question":"要望になりますが、窓口へ来ていただいた方への十分なサポート。それから、シニアスマホ教室の拡大には課題があるということで、どうしても数がなかなか難しいということでございましたが、一般質問やこれまでの議会でも申し上げていますように、工夫をしながら数を増やせる取組についてもご検討いただきたいというところ。それらぜひ進めていただきたいということで、要望として終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6160#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":36729,"voices":111}},{"id":"r05-20231130-19","meetingId":"r05-cm11","date":"2023年11月30日","dateIso":"2023-11-30","committee":"災害・環境対策特別委員会","time":"午前１０時００分～午後 １時４３分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"リサイクルのほうで伺いたいのですけれども、まずこの間の、法律の関係のご説明が少しあったのですが、リサイクルについて国のほうでの流れというものはどのようになっているのか。伺いたいと思います。捉え方です。","respondent":"品川品川区清掃事務所長","answer":"それに対する区の考えですが、先ほど少し説明したとおり、近年ではちょっと、一定の伸びが出ない傾向がありますので、やはりここを伸ばしていく策をこれから取り組んでいかなければいけないと、このように思っております。","voiceIndex":6,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"拠点回収のところでは少し増えてきているのですか、という感じなのですけれども、今区内では、単純に考えると、人口が増えてきているところで考えると、資源、単純な量でいけば増えていくのかなと思うのですが、それが明らかに増えていくということにはなっていないということは、区としてはどのようにお考えなのか伺いたいと思います。","respondent":"品川品川区清掃事務所長","answer":"最近では大分、何というのですか、通販ですか、そのようなものが増えて、やはり段ボールの量などは意外と多くなっている傾向はあるのではないかなと考えています。","voiceIndex":8,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"廃棄物の量に合わせて、資源リサイクルも増えているということなので、そうしたら、それをやはりさらに前に進めていけるように、力を尽くしていただきたいと思います。そもそもごみを出すということを減らしていくということで、区としてもそのような姿勢だということなので、それをさらに進めていっていただきたいと思いますが、何か具体的な取組、考えていらっしゃることがあれば伺いたいと思います。","respondent":"品川品川区清掃事務所長","answer":"現状の製品プラスチックの中での課題というところですけれども、６月から進めているところですが、説明会等をやっていても区民の皆様の理解度が非常に高いというか、私も長年説明会などやっているのですけれども、これだけ。","voiceIndex":10,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうですね。区民の方々は、何が対象なのかということは、多分日々迷うようになってしまうと思うので、ぜひこれは進めていっていただいて、多くリサイクルできるようにしていっていただきたいと思います。私もハンガーなどリサイクルされるということになると助かるなと思います。そういったところでも、区としても発信をしていっていただきたいと、これは要望しておきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-004"},{"speaker":"吉田委員","kind":"確認","question":"何点か伺いたいと思います。この古紙の中に平成３０年度から雑紙が入っているのかどうか伺いたいと思います。１点。それから、この集団回収の中の紙パックというものは、牛乳のパックのことをいっておられるのか、その点も確認したいと思います。それから、よく学校やＰＴＡが回収しているのは、この集団回収のほうに含まれて実績が出ているのか、その３点伺います。","respondent":"品川品川区清掃事務所長","answer":"集団回収としてこちらに登録をしてあれば、集団回収団体としてＰＴＡがやっているという傾向もありますし、学校によっては未登録でやっている場合もあるのかなと考えていますので、ちょっとＰＴＡの回収については。","voiceIndex":14,"id":"exchange-005"},{"speaker":"吉田委員","kind":"質問","question":"雑紙については分かりました。うちの会派の中で「このチラシ届いた」と聞いても「来ていない」という方が多いのですけれども、どのような形で、私は、「あっ、説明会しろしろと言ってきちんと配られている、すごい」と思ったのですが、みんな知らないと言うので、どのような配られ方だったのかなと思って伺いたいと思います。","respondent":"品川品川区清掃事務所長","answer":"製品プラスチックの説明会のほうですが、こちらについては、すみません、全戸配布をしているつもりなのですけれども、多分ちょっと一部に漏れがあったのかなと考えているところです。","voiceIndex":16,"id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、私が「これ配られた、配られた」と聞くから、「いや、うちは来ていないよ」と言うのであって、配られていないことに気づかないと思うのです。ですから、周辺でいうと配られていないというお答えのほうが多いので、その辺どうして配られなかったのか、調べていただけたらと思います。その辺、庁内での徹底といいますか、そのようなものはできているか、今後どのようにしていくか伺いたいと思います。","respondent":"河内環境課長","answer":"ただ、今の段階ではなかなか、エコルとごしにつきましては、原則紙のもの、いわゆるパラフィンを折ってというところで、非常に手が込んで、まだまだコスト的に悪いというところで、そういったところの目を厳しく見ながら、まだお時間がかかって本当に申し訳ないのですが。","voiceIndex":18,"id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"今、本当に地球全体の危機的な状況なわけです。だから、その辺は若干ではない、とても危機感あおって、本当に全体で進めていかなければいけないことだということを、ぜひ徹底していただきたいと思います。これはもう強い要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"何点かご質問させていただきたいと思います。最後に、プラスチック製品回収については６月からモデル回収を実施されていると思われますが、その中で、回収後に新たに見えてきた問題点や課題などがあれば教えてもらいたいと思います。","respondent":"品川品川区清掃事務所長","answer":"１点目、啓発講座のほうですけれども、すみません、少し説明不足がありました。親子の部分もやっておりまして、このごみ追っかけ隊というところに付随しまして、夏休みに親子でリサイクル工場を見学に行こうというツアーを、今年度も夏にやらせていただいております。","voiceIndex":22,"id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問","question":"各家庭では出し方は簡易的ですが、年間の予測で回収量が約４００トンであれば、毎週約８.３トンの選別作業になると思われます。改めて、東京資源回収センターでの現場の声など調査して、もう十分に検討されてきたことだと思われますが、この製品だけは種類別に出すなど、各家庭の回収の仕方で改善できることがあればと思いますけれども、その辺についてもう一度お聞きできればと思います。","respondent":"品川品川区清掃事務所長","answer":"ただ、これから量が増えていくことによって、そのような負担感も出てくるかなとも思いますし、１つには分別して出すという手段もあると思いますし、また、リサイクル技術というものは年々すごく進んできているところで。","voiceIndex":24,"id":"exchange-010"},{"speaker":"ひがし委員","kind":"提案","question":"私からは１点だけ、以前も提案させていただいたかもしれないのですけれども、結構分別というものは、区民の目からするといろいろと細かく分かれていて難しいなどと思ったりして、私も分別でごみを出すときにネットで調べて、どこに出したらいいのだろうなどと細かく調べているのですけれども、品川区のごみの分別一覧を開くと、紙ベースというか、あいうえお順で書かれていて。","respondent":"品川品川区清掃事務所長","answer":"今後また区民の方に使いやすいような形で、アプリやチャットのほう、何とかやっていきたいように進めていきたいと考えております。","voiceIndex":27,"id":"exchange-011"},{"speaker":"澤田委員","kind":"質問","question":"今ひがし委員が質問されたことも、私もちょっと気になっていたのですけれども、以前予算特別委員会で、ＡＩチャットボットどうでしょうかということを質問しましたが、今まだ検討中というか、いろいろ調べていただいているところなのでしょうか。","respondent":"品川品川区清掃事務所長","answer":"委員のおっしゃるとおりで、現在研究をしているところで、いろいろと物事を進めるためには、自治体の中では予算というハードルもありながら、そのようなところを越えていくように、日々努力をしているというような状況です。","voiceIndex":31,"id":"exchange-012"},{"speaker":"澤田委員","kind":"質問・要望","question":"そうですよね。別の質問なのですけれども、今のは要望で、すみません、リサイクル通信の発行部数が今約１万３,０００戸で、全戸配布ではないのではないですか。","respondent":"品川品川区清掃事務所長","answer":"リサイクル通信等の全戸配布、そうですね、もうどうしてもコスト面など、そのようなところと兼ね合いになると思いますので、ただ、やっていくことについては、非常に効果もあることですし、一定の方向で、何か啓発方法は随時考えていきたいと思いますので、１つの案として。","voiceIndex":33,"id":"exchange-013"},{"speaker":"澤田委員","kind":"質問","question":"ぜひお願いいたします。今度はオイシックスと産学官連携で、今度またちょっと違う話なのですが、中学生による食品ロス食材を活用したメニューを考案する取組が行われていると思うのですけれども、楽しみながら食材を無駄にしないことを学べる、すばらしい機会になっていると思います。今後、ほかの中学校で行われる予定はあるのでしょうか。いかがでしょうか。","respondent":"河内環境課長","answer":"一方で、この場合は特別な授業を設けていただいているというようなところもございまして、こういった要望があれば、環境課、あるいはエコルとごしの指定管理者なども柔軟に対応していきたいという姿勢は変わりございませんので。","voiceIndex":35,"id":"exchange-014"},{"speaker":"澤田委員","kind":"質問・要望","question":"ということは、この学校側などから要望がないと、特にやっていないということなのでしょうか。","respondent":"河内環境課長","answer":"そういったもののために、あえてですけれども、ここですと青稜中学校だとか、具体的な学校名も出しつつも、こういった連携を進めているので皆様いかがですかという啓発の力を入れていると。","voiceIndex":37,"id":"exchange-015"},{"speaker":"こしば委員","kind":"確認","question":"私からは資源ステーション回収のところで、確認の意味も込めてお聞きしたいのですけれども、まずこちらのステーションなのですが、１万か所ということで、これまずは１万か所以外のところでの資源回収というものはされておるのかしていないのか、その資源回収のごみの種類がありますけれども、それぞれの地域で曜日は異なっていると思うのですが、まずそこの確認だけさせてください。","respondent":"品川品川区清掃事務所長","answer":"すみません。ちょっと説明があれでしたけれども、そこの資源ステーションというものは、週１回回収している場所のことを示しています。","voiceIndex":41,"id":"exchange-016"},{"speaker":"こしば委員","kind":"質問","question":"それと、これからプラスチック製容器包装のところで、これまでは燃やせるごみの中で扱われていたプラスチックが、今度はプラスチックのほうに入ってくるとなると、大量にごみが増えてくると思うのですけれども、その辺の回収車両への影響含めて、どういったように見込んでおるのか、ちょっと教えていただければと思います。","respondent":"品川品川区清掃事務所長","answer":"状況が変わり次第、車のほうについては対応していこうかと考えています。","voiceIndex":43,"id":"exchange-017"},{"speaker":"こしば委員","kind":"意見","question":"どうもありがとうあります。現状では、今のところは車の台数に、恐らく大きな変化はないだろうというような見立てということ、かしこまりました。その辺との連携について、現状も含めて、今後についてのお話をいただければと思います。","respondent":"品川品川区清掃事務所長","answer":"このプラスチック関係で、やはり各企業も製造者責任というところを負われているところがありまして、今割と、例えば大井町のほうのイトーヨーカ堂など、そのような大手スーパーを利用した形で、そこに回収ボックスを置いて、やはりどうしても各企業。","voiceIndex":45,"id":"exchange-018"},{"speaker":"こしば委員","kind":"質問・要望","question":"そうですね。企業もやはりどうしても利益を求めるので、関心はあるのだけれどもなかなかその先に進まないというところもあるのですが、それでも必ずどこか着地点が見いだせてくるのかなという期待を持っておりますので、ここからまたよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-019"},{"speaker":"西村委員","kind":"質問・要望","question":"今日まさに地元が資源ごみの日でして、今のこしば委員の質問にもありましたけれども、資源ごみの出し方についてちょっと伺いたいなと。正しいごみの捨て方のルールを知っていただくだけではない課題があるような気がしておりまして、お考えがあればお聞かせいただきたい。","respondent":"品川品川区清掃事務所長","answer":"例えばボックスが足りなければ、清掃事務所のほうにご連絡いただければ、増やすということは容易にできるところなのですけれども、ただ、その連絡するというところを分かっていない方も当然いらっしゃると思いますので、今やっている対策としましては。","voiceIndex":49,"id":"exchange-020"},{"speaker":"新妻委員","kind":"質問・要望","question":"ご説明ありがとうございました。ちょっとまず１点、最初に確認させていただきたいことが、区有庁舎の中でもしっかりと分別をしてリサイクルされていると思うのですけれども、区有庁舎における、このリサイクルをしている中での効果というか、評価をどうされているのかというところをちょっとお聞きしたいと思います。","respondent":"品川品川区清掃事務所長","answer":"ただ、この庁舎については、リサイクルを進めるところでは、清掃事務所のほうもいろいろと対応しているところがありまして、分別方法については、同様に、一般家庭と同様な形で分別のほうを進めて、効果としましては、大分大きな量をリサイクルに回しているような状況ですので。","voiceIndex":53,"id":"exchange-021"},{"speaker":"新妻委員","kind":"質問・要望","question":"これは非常に難しいことだと思うのですが、今後、区としての検討をされている中で、この２つに関してどのようなことを検討されているのかということをお知らせいただきたいと思います。今後、またもう一層の食品ロス削減の取組として、そのような民間事業者と連携をしての取組を、自治体として、品川区としてやっていただきたいと思うのですが、そのようなご検討や、またお考えをお聞きしたいと思います。","respondent":"品川品川区清掃事務所長、河内環境課長","answer":"こちらをうまく、何かこう活用してできないかなというところで、現在は進めているようなところがあります。ただ、これは実際にやるとなると、現在の可燃ごみの中の生ごみを分別して出してくださいということになります。そういったところの知見も応用しながら、やはり食を見つめ直し、日本のエネルギーやＣＯ２について見つめ直すものを、しっかり機会を捉えて広げていきたいというところで。","voiceIndex":55,"id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"何かよい方法があればいいのかと思うのですが。それで、そのようなところに一度、恐らくやられていると思うのですけれども、マンションにご協力いただいて、何か見やすいパネル等を、一定期間でもいいですから、１か月間ちょっとやってください、半年後にまた掲示してくださいというような、何かそのような工夫をして、出すけれども、そのとき一緒に見られるというような対応も大事なのかなと。１軒１軒。","respondent":"品川品川区清掃事務所長","answer":"例えば資源ステーションのところで何かあるときには、先ほども説明したとおりパトロールの職員などが個別に対応するというような状況もありますし、あと、そうですね、看板設置なども、やったりもしておりますので、ただ、何というのですか、このような対応をすると。","voiceIndex":59,"id":"exchange-023"},{"speaker":"須貝委員","kind":"質問・要望","question":"本当に大変な事業だと思います。外国の方もいらっしゃるので、できれば、その若者をターゲットにして、できるだけ掲示してどうなのかなというものを、１人でも２人でもきちんと分別して出してもらえるように、今後も努力をしていただきたいと思います。ここでちょっと２点だけお伺いしますが、太陽光パネルというものが３０年たつと寿命が来るという話を聞いています。私もお総菜、結構買います。","respondent":"河内環境課長","answer":"売る側には売る側の理屈もあるかと思うのですが、一方、例えば恵方巻きの問題など、昨今あったかと思います。そういったところを踏まえまして、こういったところの改善方向に、区としてしっかり取り組んでいきたいという考えです。","voiceIndex":61,"id":"exchange-024"},{"speaker":"せりざわ委員","kind":"提案","question":"何点かお伺いをしたいと思います。それをぜひ清掃事務所でやってほしいなと思って、また、これから資源循環推進担当課ですか、新しいものができるという話もあると思うので、ぜひこれは予算をしっかり取り続けてほしいなと思っています。この２つ、お話をお伺いできればと思います。","respondent":"品川品川区清掃事務所長","answer":"単価が教育委員会の大体見込み、やっている実績ですと、キロ２０円ぐらいになるのです。そうすると、やはりどうしても億超えるお金が必要になってきます。そういったコスト面もいろいろ考えながらやっていく必要があるかなと考えています。","voiceIndex":64,"id":"exchange-025"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"事業者などから聞くのですけれども、それは多分持ち去られたかどうか分からなくなっただけなのではないかなとも思っているので、そのような意味でいえば、やはりまず今の拠点回収の段階で持ち去っているかどうかをしっかり、逆に今時点で取り締まっておかなければ、戸別回収に今後なったときに、もう取締りがかなり難しくなるのだと思うので、拠点回収の段階でしっかり、その人が生計立てているということは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-026"},{"speaker":"つる委員","kind":"提案","question":"大丈夫ですか。そのようなものがある。こちらがやろうとしていることの趣旨をどう伝えていくかと。ですから、全体合わせて、この辺の、何というのでしょう、いわゆる区民運動としてどう全体を動かしていく、何かツールという部分や、今申し上げた広報の工夫など。感謝。ですから、ぜひそのような広報の工夫や、区民運動をどう今後持っていくかということを、ちょっと全体の話で教えていただければと思います。","respondent":"河内環境課長、品川品川区清掃事務所長","answer":"そういったところも含めまして、全体の区民の見方が変わるように、区民運動、国民運動と、大変重いテーマですが、重いテーマだけに、区民の皆さんがお気軽にということは変ですけれども。清掃事務所についても、基本的に環境課と連携した形で、広報のほう進めていけることが一番理想かと思いますので、そのような方向性でやっていきたいというところと、それから分別等、そのようなところも、既存のもので。","voiceIndex":69,"id":"exchange-027"},{"speaker":"つる委員","kind":"質問・要望","question":"そのような視点のもったいないを持っていただきたいなと思っています。ですから、そのような工夫というところをまさにやっていただきたいなと思います。そういったところなので、今後その辺を展開していくに当たって、ぜひ、今の広報の工夫、これはぜひもったいなくならないようにやっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-028"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"そのプラスチックのリサイクルというものが、地球温暖化にとってもすごく重要なのだという、ＣＯ２削減にとってもとても大事なことなのだというところは、ぜひその啓発の中に入れていただきたいなと思っているのですけれども、ここ、サーマルリサイクルということも、区としても進めてきた部分であると思うのですが、サーマルリサイクルよりもプラスチックのリサイクルということが。","respondent":"品川品川区清掃事務所長","answer":"当然プラスチックは、多分普通の可燃ごみの中でも、ＣＯ２発生量は非常に多いものですので、そういった点も説明していこうかなと考えています。","voiceIndex":74,"id":"exchange-029"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"そのようなところからすると、もしも処分というようななことになるのであれば、区役所でもいいですし、地域センターなどでもいいですし、そのようなところで、もし必要な方があったらご自由にお持ちくださいというような形でしていただくと、助かる方はすごくたくさんいらっしゃるのではないかなと思っていまして、清掃の方からも。","respondent":"平原防災課長","answer":"今、災害備蓄品の廃棄のお話がありましたので、私のほうからお答えします。以前こちらで備蓄物資のお話をさせていただいたときに、担当の課長から、現在品川区における災害備蓄品、水、食料等につきましては、全て有効活用させていただいているというお話をさせていただきました。","voiceIndex":76,"id":"exchange-030"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"もしもそのようなことが実際にあるのだとしたら、ぜひそのように、困っている方にとってはすごく助かるものなので、そのようなご活用も含めてご検討いただきたいということで、要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-031"}]},{"id":"topic-02","title":"環境学習動画","agenda":"環境学習動画","exchanges":[{"speaker":"つる委員","kind":"確認","question":"ごめんなさい。１点だけ確認は、これ今年度、たしか夏配布されなかったＥＣＯｍｉｃ、エコラが載っている漫画のものが動画になったという、当然内容など充実されているのでしょうけれども、そのようなことでいいのか教えてください。","respondent":"河内環境課長","answer":"紙冊子ですが、電子化することによりまして、利用される分母の計算も、そちらの部分につきましては、全て電子化によりまして展開を予定しております。","voiceIndex":83,"id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6646#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":46047,"voices":91}},{"id":"r05-20231130-10","meetingId":"r05-cm11","date":"2023年11月30日","dateIso":"2023-11-30","committee":"議会運営委員会","time":"午後 ０時４５分～午後 ０時４７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5526#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":1355,"voices":8}},{"id":"r05-20231205-10","meetingId":"r05-cm12","date":"2023年12月5日","dateIso":"2023-12-05","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時４０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"陳情の理由の一番上にあるように、委員会での質疑というのは、付託をされて、実質的な審議をやるものですから、区民の皆さん、とりわけ請願や陳情を出した方にとってはかなり関心が高いものだと思います。何といっても開かれた議会をつくる上でも、ライブ配信というのは、ルールさえつくれば、すぐにでも実施できると私は思いますので、すべきだと思いますけれども、皆さんどのようにお考えなのか。","respondent":"あくつ副議長、大澤区議会事務局長","answer":"今、安藤委員のお話の中で、本会議場では傍聴者によるＳＮＳでのライブ配信は認められているというお話があったのですが。録画を許可するということで、この後の配信については制限をしていないということで、許可をしているという考え方ではございません。録画は認められている。そのまま流すかどうかは、議会として許可をしているということではないということは確認させていただきました。","voiceIndex":4,"id":"exchange-001"},{"speaker":"須貝委員","kind":"質問","question":"広い委員会室が物理的にできた、またはそういうところで委員会、いろいろ審議できるような場所があったら、ライブ配信ですか、そういうものもやっていいと私は思うのですが、今の段階でそこに大勢の傍聴者が見えて、さらに撮影云々ということになると、それはちょっといかがなものかなというふうに思いますので、広い委員会室ができたときに、利用できるようなときがきたら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-002"},{"speaker":"山本委員","kind":"確認","question":"一方で、一部だけ切り出されたときに誤って伝わるといったリスクもあるかなというふうに思っております。区民の皆様に正しい情報を展開していくという責任がありますので、誤解を生むように切り取られて配信された場合などに備えて、やはり区議会が発信して、確認することができる状態にしておくことは、十分に考慮する必要があるというふうに考えております。陳情第４７号については……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"許可でないというのは、正確には分かりました。今は機器とかも様々ありますので、狭いスペースの中でも配信できるようなルールをつくればいいのではないかと私は思うので、そこら辺についてもクリアできるのではないかというふうに思いますけれども、皆さん、そこら辺はどうですか。スペース上、問題があるとか、ちょっと厳しいのではないかとか、そういった点についてはどうでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"山本委員","kind":"確認","question":"陳情第４７号についても併せて申し上げます。その中で、正しいものは何かということが確認できる状況にしておくことは、区民の皆様に区議会の情報を正しく伝えていくということでは、とても大事であると思います。これと併せて予算特別委員会、決算特別委員会についても傍聴者の皆様のライブ配信も考えていくべきであるというふうに考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-005"},{"speaker":"須貝委員","kind":"確認","question":"先ほど申し上げましたけれども、いずれはこういう方向に、ライブ配信を各常任委員会で行うと思うのですが、繰り返しますと、まずハードの面で、スペースがあるところで多くの方が見に来られるということを想定して考えて、十分な座席数、それから傍聴できる場所があるかどうかを確認した上、さらにせっかく議会改革のための会議があるのですから、そちらのほうで十分審議されて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-006"},{"speaker":"安藤委員","kind":"提案","question":"区民に開かれた議会という議会改革の中心中の中心だと思うのですけれども、これを進める上で重要なことだなと私は思っていますし、私は個人的にもかなりこの問題は打開すべきだなということで、何回か提案もさせていただいていたのです。質問があるのですが、そもそも委員会は委員会室でという規定については、特に規定というのはないということでよろしかったのか、ちょっとそこだけ確認させてもらえますか。","respondent":"大澤区議会事務局長","answer":"委員会は委員会室でやらなければいけないという規則はございませんけれども、どこでやるかというのは議会運営委員会の中でその都度確認しているものだと認識しています。","voiceIndex":15,"id":"exchange-007"},{"speaker":"安藤委員","kind":"提案","question":"理事者の入替えとかのところは、席数が課題になるかもしれませんけれども、現状の第一委員会室でも、パイプ椅子を並べて後ろのほうに待機していただくということもあります。様々な課題はあると思いますが、ぜひこれは踏み出してみるというのが、陳情者の方、区民の皆さんがこれだけ議会の議論に関心を持っているということなのですから、それに応えるべきなのではないかなというふうに私は思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":17,"id":"exchange-008"},{"speaker":"塚本委員","kind":"質問","question":"本日結論を出します。結論は不採択です。他自治体でも同じようなことがあったりもしていますし、そういうふうに捉えておりますので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-009"},{"speaker":"安藤委員","kind":"提案","question":"本日結論を出して、採択を主張します。やはり開かれた議会をつくる上で、特に委員会の中継を強く求める区民の皆さんの提案ということもありますので、現状すぐにもできる工夫ということで、こういうことをやっていくというのは、すごく議会改革につながると私は思いますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-010"},{"speaker":"須貝委員","kind":"意見","question":"先ほども申し上げましたが、結論を出すということと、不採択です。初めてこういう陳情が出てきて、こういうふうにライブ配信して区民に見せるということはいいことなのです。ただ、今、物理的な問題とかが様々あるので、そこは議会にある議会改革を検討する会議でしっかり審議して、そちらの場所で皆さんで検討されて、最後に議会運営委員会で決められたらいいのかなというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-011"},{"speaker":"塚本委員","kind":"意見","question":"理由としては、本会議場であれば傍聴できるではないかという視点での陳情なのですけれども、傍聴が可能となるということは、平場で一問一答という非常に真剣な議論がなされる予算特別委員会、決算特別委員会ということで、まず委員、理事者の発言がしっかり保たれることがあって、その上で傍聴ということをしっかりと考えていくということだと思いますので、本会議場で今の予算特別委員会。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":28,"id":"exchange-012"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、採択なのですが、今、新庁舎の検討も進んでおりますけれども、イレギュラーなことだとは思うのですけれども、やはり新庁舎での決算および予算の特別委員会は、恐らくフルスペックの傍聴は課題が解消されると思うのですけれども、あまりに時間もかかりますし、それまで暫定的に、今あるものを使って。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":30,"id":"exchange-013"},{"speaker":"須貝委員","kind":"意見","question":"私も本日結論を出すということと、不採択でお願いします。これも第４６号と同様に、初めての陳情なので、今後、議会改革を検討する会議でしっかり議論して、最後、議会運営委員会で決められたらいいかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":31,"id":"exchange-014"}]},{"id":"topic-02","title":"議会運営上の変更","agenda":"議会運営上の変更","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"今回議席を変更するということで、理由もなく変更するというのはまずいと思うのです。議会運営委員会の中で、こういう申出があって、こういう状況なので議席を変更しましたというふうなことをちゃんと残しておくべきだと思うのです。そうしないと、今後勝手にどんどん移動できることになってしまうので、その辺、委員長はどう思われますか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-015"},{"speaker":"松永委員","kind":"質問・要望","question":"前回の一般質問の際も、少しお話をさせていただきまして、木村議員に関しては足の具合が少し悪くて、この間は椅子に座って一般質問させていただいたのですが、やはり段差があるとちょっと厳しい部分がありまして、本人からも、ぜひそうしていただきたいということで、今回このような形で皆さんにご報告をしています。ぜひご理解いただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-016"}]},{"id":"topic-03","title":"令和５年第４回定例会","agenda":"令和５年第４回定例会","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"もしこの議会運営委員会の場で賛同が得られれば、ぜひ修正した内容で本会議に提案していただければと思っています。修正内容なのですけれども、口頭で説明するよりも、文章があったほうが説明しやすいので、本当に一部なのですけれども、この資料を配付させていただきたいのですけれども、委員長、よろしいですか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":43,"id":"exchange-017"},{"speaker":"安藤委員","kind":"提案","question":"提案内容なのですが、案の、第１段落の文章の最後の部分、「現地は人道的に深刻な危機に直面している」というのは、そのとおりだと思うのです。よいと思うのですけれども、なぜそうなっているかという前段の部分なのです。この案文では、「ハマスとイスラエルによるパレスチナ・ガザ地区での戦闘により」となっています。皆さんのご意見を聞かせていただければと考えています。いかがでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-018"},{"speaker":"高橋（伸）委員長","kind":"提案","question":"委員長としては、お示しした案のとおりで、議案として提案したいので、よろしくお願いします。いただいた資料に関しては、資料として預からせていただきますので、よろしくお願いいたします。今のご発言に対して何かほかにご発言はありますでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"このようにハマスの無差別攻撃とか、ミサイルによるパレスチナ・ガザ地区への攻撃、報道を聞いていると、その双方にそれぞれ主張はあるのですよね。かなり宗教絡みで、それぞれの言い分はまさにそのとおりで、ただ、やり過ぎ、どうだ云々となってくると思うのですけれども、そこは我々が文面で明記するものではないのかなという気がします。それはちょっと皆さんのご見解をお聞きしてと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-020"},{"speaker":"せりざわ委員","kind":"意見","question":"そもそもは即時停戦が目的だと思いますので、その意味で言えば、委員長案で進めていただいていいのかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":49,"id":"exchange-021"},{"speaker":"塚本委員","kind":"意見","question":"私も同様に委員長案で出していただければと思います。安藤委員は、ちょっとしたというような感じでおっしゃっていましたけれども、文字づらは少しの変更に見えるけれども、内容の方向性の変更は相当なものなので、会派に持って帰って相当議論しないと、これはなかなかいけないという部分もありますし、物理的な時間の問題もありますので、委員長案で進めていただけるといいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":50,"id":"exchange-022"},{"speaker":"松永委員","kind":"意見","question":"私たちの会派といたしましても、先ほど塚本委員からありましたけれども、時間的な問題というのもありますし、あとはどちらが悪いというわけではなくて、まず戦争自体をやめないといけないということを主張していきたいというふうに思っておりますので、委員長案のとおりでお願いしたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":51,"id":"exchange-023"},{"speaker":"安藤委員","kind":"提案","question":"皆さん、ご意見をありがとうあります。くどいようですけれども、停戦を求める決議を議会として上げるということに関しては、すごく意味があると思いますので、今回私たちの提案が合意とならなかったのはちょっと残念ですけれども、こういう決議にはもちろん提案者になった上で賛成したいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":52,"id":"exchange-024"}]},{"id":"topic-04","title":"通年での服装軽装化","agenda":"通年での服装軽装化","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"その他の(4)なのですけれども、例年２日間ぐらいに分かれていたような気がするのですが、１日で全部終わるのかということ、それと当日の説明資料を電子データでという話だったのか、そこら辺をちょっと確認させてください。","respondent":"大澤区議会事務局長","answer":"これまで２日間でやっていたのを１日にするということで、１日で終わるように、今、時間の調整をしているところと聞いてあります。資料ですけれども、資料は説明の際に配付というふうに聞いてあります。データのお話は、予算プレスのお話です。","voiceIndex":88,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"どちらに要望すればよいのか分からないですけれども、２点ありまして、一つは結構大事な説明なので、例年並みの時間は各会派取っていただければなという要望なのですけれども、もう一つは、プレス資料の件も、うちの会派としてはぜひ紙ベースでもいただきたいなと思うのです。そういった要望があるのですけれども、それは伝えてもらえますでしょうか。","respondent":"大澤区議会事務局長","answer":"ご要望としてどちらかにお伝えすることはできます。","voiceIndex":90,"id":"exchange-026"},{"speaker":"須貝委員","kind":"質問","question":"今の件ですけれども、我々はもうタブレットのほうに、ペーパーレスでやっていかなければいけないと思うので、そういう方向で共産党にもご協力願ったほうが良いのではないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5528#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":20146,"voices":95}},{"id":"r05-20231226-10","meetingId":"r05-cm12","date":"2023年12月26日","dateIso":"2023-12-26","committee":"議会運営委員会","time":"午前 ９時００分～午前 ９時３７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和５年第２回臨時会","agenda":"令和５年第２回臨時会","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"通常でしたら議案審査の２日前に資料をいただくのですが、今回は明日なので、できれば早めに補正予算議案の資料をいただければと思うのですけれども、そこら辺はいかがでしょうか。","respondent":"桑村副区長","answer":"ご意見として受け止めしますが、一つは、議案説明会で一定の議案説明をしないうちに説明資料が公式にいくというのは、なかなか難しいのかと思います。","voiceIndex":5,"id":"exchange-001"}]},{"id":"topic-02","title":"会派変更届","agenda":"会派変更届","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"その理由は、日本共産党品川地区委員会名で見解を発表し、その中身が新聞報道でも伝えられましたように、中塚区議が、猥褻な言動による性暴力、セクシュアルハラスメントを行っていたこと、それが被害者からの告発で判明し、本人にも事実確認したところ、全て事実と認めたことによるものであります。被害者は、日常生活を送ることに困難を抱えることになりました。したがって、党を除籍といたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-002"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"念のため確認させていただきたいのですが、１２月１２日、１３日と、大手新聞社の報道があって、私も報道ベースでは何となく伺ってはいるのですが、品川区議会として、いろいろお問い合わせもいただいているので念のため確認で、まず、事実として、地区委員会からの調査があって事実が認定されたというようなお話があったと思うのですが、会派としてご本人に確認をされたのでしょうかということが１点。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-003"},{"speaker":"安藤委員","kind":"確認","question":"本人と直接話して事実確認を行ったところ、全て事実と認めております。見解にもありますように、そういったことです。会派としても確認して、会派としても判断したです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-004"},{"speaker":"せりざわ委員","kind":"質問","question":"もう１点だけ。少し厳しい指摘になりますが、そうすると、今回、会派としても、もしくは党としても、地区委員会としても、セクハラという事実認定をされたということだと思いますが、今回、離脱になって無所属にはなりますけれども、区議会にセクハラをされた方が今後も居るわけであります。それに対して、会派から何か行動を起こすというようなイメージはあるのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"共産党からは、辞職勧告決議案等を出す考えはないのですが、ただ、議員辞職すべきだと強く思っておりますし、共産党としても、本人に繰り返し辞職を求めてきたところです。仮に決議案が出された場合は、賛成するつもりです。その際も、繰り返すようですが、二次被害を避けるという観点から、地区委員会の見解以上のことをお話しすることはいたしません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-006"},{"speaker":"須貝委員","kind":"意見","question":"今、共産党のお話を聞いたのですが、我々も新聞報道、それから、共産党の赤旗新聞で公表されているという話を聞きまして、文面も読ませていただきました。今この場で話すべきかどうかは分かりません。で委員長のほうからなのかもしれませんが、私は、明確にこういう事実を相互に認めているということならば、議員辞職勧告決議案を品川区議会として提出するべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":20,"id":"exchange-007"},{"speaker":"塚本委員","kind":"質問・要望","question":"これは事務局にお聞きしたいのですけれども、いわゆる過去の事例などで、何かこういった対応をとってきたということがあったりするのか。あるいは、明文化されないまでも、内規みたいなものがあって、こういう対応をとるように定められているみたいなところがあるのか、そこのところを教えていただきたいと思います。","respondent":"大澤区議会事務局長","answer":"品川区議会としては、過去にこのような事例はございません。規程も特には、今のところはないです。","voiceIndex":22,"id":"exchange-008"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、いわゆる辞職勧告決議案というのは、時々、他の自治体などでも出てきたりして見聞きをするのですけれども、ほかには何かそういう、問責決議というものがあったか、そういうものとか、何か幾つか、議会として、他の自治体の例などを踏まえた上での対応の在り方というのか、手法というのか、そういうものが、どういったものになるのかということが今の段階で分かれば教えてください。","respondent":"大澤区議会事務局長","answer":"件数としては少ないですけれども、被害者から陳情書をもって決議案を提出したりですとか、あとは、辞職勧告のほかには、不祥事には毅然と対応し、議会の信頼回復に努めることを誓う決議案を提出している場合がございました。","voiceIndex":24,"id":"exchange-009"},{"speaker":"塚本委員","kind":"意見","question":"分かりました。今後、区議会として必要な対応、とるべき対応は、少し検討する必要もあるかと思いますけれども、その一方で、また、共産党の会派としては、本人にも話を聞いているというお話でしたけれども、本人から、区議会として弁明等を聞く機会も一定必要かなとも思います。いずれにしても、また新たな検討ということでは、何ができるかということを考えていく必要があるかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":26,"id":"exchange-010"},{"speaker":"安藤委員","kind":"提案","question":"辞職勧告決議については、共産党から必ず出さないということを今の時点で明言してしまうこともどうかなと、今少し思い直しているところがありまして、なぜ出さないと言ったかというと、繰り返しますけれども、私たちとしては、そういったことを起こした以上は、議員は辞めるべきだと強く思っておりますし、それはもちろん何回も言ったわけですが、辞職勧告決議となりますと、私たちとしては。","respondent":"あくつ副議長","answer":"いわゆる本人からの何かしらの発信がない中で、それは共産党しか分かり得ない状況であって、そのようにご主張されるのであれば、先ほど、その可能性は排除しないというお言葉もいただいたので、それはよくよくご検討いただきたいと思います。","voiceIndex":32,"id":"exchange-011"},{"speaker":"山本委員","kind":"意見","question":"当会派としても、今までの話を踏まえましても、議会として何らかの対策をとっていくべきではないかと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":35,"id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5530#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":12916,"voices":63}},{"id":"r05-20231227-6","meetingId":"r05-cm12","date":"2023年12月27日","dateIso":"2023-12-27","committee":"区民委員会","time":"午前１０時０７分～午前１１時１７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第１０３号議案、令和５年度品川区一般会計補正予算（歳出等 区民委員会所管分）","agenda":"第１０３号議案、令和５年度品川区一般会計補正予算（歳出等 区民委員会所管分）","exchanges":[{"speaker":"山本委員","kind":"質問","question":"ご説明、ありがとうございました。本件は長期化する物価対策ということで、区民生活の下支えと区内経済の活性化のために必要な取組と評価しております。プレミアム付区内共通商品券事業についてお伺いします。例年と比較して発行総額を増額したこと、それからプレミアム率を増加させたこと、それから前倒しにされたことというのはどういった意図や背景があるのかという、区の考えをお聞かせください。","respondent":"小林商業・ものづくり課長","answer":"こうした中で、消費喚起を行うことによりまして、区民生活の下支え、区内経済の活性化というところで、発行総額につきましても例年に比べて大きく増やし、かつプレミアム率も大きく増やすとやはり消費喚起も大きくなるというところで。","voiceIndex":5,"id":"exchange-001"},{"speaker":"山本委員","kind":"質問","question":"ご回答ありがとうあります。その中で、これは区民生活の下支えと区内経済の活性化の両立が図れるという意図だと思うのですけれども、これまでの利用実績の中で、品川区在住の方がどれぐらい使われているのかというのが、もし分かるようでしたら教えていただければと思います。","respondent":"小林商業・ものづくり課長","answer":"そのことを通じまして、商店街などでたくさん消費をしていただくというようなことを目的としている事業です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"山本委員","kind":"質問","question":"質問の意図がうまく伝わらなかったようなので、もう一回質問しますと、ご説明のとおり、このプレミアム付区内共通商品券については、品川区在住にかかわらず購入ができると理解しております。その中で、区民の方がどれだけ使われているのかということ、買われているかということを把握したいとお聞きした次第です。これは申込のときに分かるのかどうかというところも含めて、ご回答いただければと思います。","respondent":"小林商業・ものづくり課長","answer":"ただ、実際に住所別の購入予定者がどういうところにいらっしゃるかというと、ほとんどが区内の方でいらっしゃって、大田区、目黒区、世田谷区、港区の方も若干いらっしゃいますけれども、大半は区内の方ということで把握しています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"山本委員","kind":"質問・要望","question":"ご答弁ありがとうございました。やはりこういった実態というのはしっかりと確認していったほうが、せっかく施策としてやりますので、効果検証というところで言うと、区民の方がしっかり使われているのかどうかという確認を、今後の機会ではやっていただきたいと思います。これは要望です。続いて、キャッシュレス決済ポイント還元事業について伺います。幾つか確認をさせてください。","respondent":"小林商業・ものづくり課長","answer":"先ほど少し申し上げたように、令和４年度に実施した場合でいきますと、４事業者からいろいろデータも頂くのですけれども、その中で、やはり我々としましては生活に身近な分野で、実際区民以外の方もいらっしゃいますけれども。","voiceIndex":11,"id":"exchange-004"},{"speaker":"山本委員","kind":"質問・要望","question":"何点か確認をさせていただければと思います。これは先ほどのご答弁の中では分かりませんでしたので、改めて教えていただきたいと思います。それから債務負担行為についてのご答弁なのですけれども、法令に基づき契約準備が必要だということで、必要なことはしっかりやっていただければと思うのですが、これは業務委託先、相手方というのは特に決まっているのでしょうか。それとも今後選定されるのでしょうか。","respondent":"小林商業・ものづくり課長","answer":"契約の委託先が決まっているのかですけれども、これから議決いただいて調整ですので、まだ現時点で具体的にどうするかというところは、これからの検討です。","voiceIndex":13,"id":"exchange-005"},{"speaker":"山本委員","kind":"質問・要望","question":"ご答弁ありがとうございました。スケジュールでこれぐらいの時間がかかるということですけれども、世田谷区、渋谷区のように一度インフラを整えてしまえば、その後は迅速にこういった景気刺激策などができるということもありますので、そういったところについて検討をしていただきたいということで、これは要望で質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-006"},{"speaker":"えのした委員","kind":"質問","question":"そういった方は多いので、この周知方法として毎回周知をどうするかというのはありますが、それはこのキャッシュレス決済で２０％のポイント還元を行いますという周知だと思うのですが、できれば一番いいのはやはり区民の方に多く利用していただければ、区民の方も喜ばれて、区内の事業者も潤う、活性化するということになってつながってくると私も考えていますので、例えば今まで特に高齢者の方に対して。","respondent":"小林商業・ものづくり課長","answer":"区民利用を広げるためにですけれども、我々としましては広報しながわをはじめ、ホームページの専用ページも作って前回は実施して、幅広く目に留まるようにして使っていただくということで、我々は今回もこの事業が幅広く皆さんの目に留まるように。","voiceIndex":16,"id":"exchange-007"},{"speaker":"えのした委員","kind":"意見","question":"やはり周知もすごく重要なのですが、区民の方へより丁寧なアドバイスではないですけれども、それをお願いしたいです。スマホは高齢者の方も結構お持ちで、ＬＩＮＥなどは特にお孫さんですとかとの写真のやりとりなどに使っているような光景が見受けられるのですけれども、支払に関してはやはりまだまだ利用されている方が少ないと思いますので、そこら辺の取組も今後進めていっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":18,"id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問・要望","question":"かなり切れ目がない形で、区民と区民生活と、あと事業者の事業を支援するという形になっていると思うのですけれども、その辺りの、補正予算というのは我々の認識ではやはり年度内に使い切らなくてはいけないという認識があったのですが、繰越明許費と債務負担行為と、先ほども山本委員の質問でありましたが、債務負担行為については。","respondent":"小林商業・ものづくり課長","answer":"切れ目のない経済対策ですけれども、ご指摘のとおり、まだ報道レベルではありますけれども、東京都が先日、報道にあるような事業というところでは、補正予算のプレスリリースで「暮らし向き向上緊急サポート事業」ということで。","voiceIndex":19,"id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問","question":"意図はよく分かりました。それでもう一点だけ。大丈夫だとは思うのですけれども、国のほうはこの補正予算ですから、本来であれば年度内で消化というか、それを使わなければいけない。繰越明許費でも来年度もいいのですよということで、これは大丈夫なのでしょうか。","respondent":"小林商業・ものづくり課長","answer":"今回、都の支出金という形で入れるのが、紙のプレミアム付区内共通商品券事業のほうですけれども、こちらは企画部にも確認をして、こういったような予算執行で問題ないかというところで調整して、今回実施するものです。","voiceIndex":21,"id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問・要望","question":"三億数千万円の予算の中で２億１,０００万円をこちらに投入されるということでしたので、非常に割合が大きいというところで、それは全然ウェルカムですし、我々も要望していたことですからありがたいと考えていますが、スキームについてはまた私たちも研究していきたいと思います。もう一つだけ。ただ一方で都のほうなのですが、都内のコンビニや飲食店、美・理容店で使えるというような報道があります。","respondent":"小林商業・ものづくり課長","answer":"先ほどご指摘のありましたような区内のスーパーでいきますと、中小企業基本法で中小企業に位置づけられる資本金なり従業員の数というのも確認しつつ運営事業者と調整しまして、その中で分類されるものにつきましては、先ほど具体名を挙げていただきましたけれども。","voiceIndex":23,"id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それはどちらに重きを置くのかというところで、そこについてはぜひ、例えばタバコには使えないと、物価高騰対策重点支援地方創生臨時交付金のものはタバコを買ってはいけませんなどいろいろ縛りがあるのですけれども、そういうところも、これから全く同じものをやるということではなくて、この前アンケートを取ったのであるならば、また分析をしているのであれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"プレミアム付区内共通商品券についてお伺いしますが、今回内容がよく分からないのですけれども、これは１冊１万円で、１人１冊しか買えないのですか。買える上限はあるのですか。買える範囲というのはどうなっているのですか。申し込む方が多ければ調整して、希望の商品券の数、金額まではいかないかもしれないけれども、調整するのですか。何で今回こういう形の事業内容の説明になったのでしょうか。","respondent":"小林商業・ものづくり課長","answer":"チラシなどでは、これはまだ作成はしていない段階ですけれども、品川区商店街連合会のほうで発行する冊子ではタイトルがございまして、一番上のところに、今委員からご指摘があったような。","voiceIndex":26,"id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"今の説明だと、これから品川区商店街連合会と調整して決めていくということですか。そういうお話であるならば、先ほど区外の方にもというお話があったけれども、区内の方の分の数を減らして区外の方にというのは、私個人の考えでは、区民への施策ですから、まずは区民の申込希望を優先して、その後にという思いが私の気持ちの中にはあるのです。","respondent":"小林商業・ものづくり課長","answer":"品川区商店街連合会と調整というところではありますけれども、今、話としてはもう既に進めているところでございまして、４冊というのは過去ずっと一つのルールで申込の上限というか、幅広く買っていただくという観点からやっているところですので。","voiceIndex":28,"id":"exchange-014"},{"speaker":"藤原委員","kind":"質問・要望","question":"最後に、同じことを何回も言うかもしれませんけれども、せっかくこうやって補正予算に出ているのだから、４冊までですよとか、４冊以上になったら抽選ですよというのは、そういう大事なことはやはり資料に書いておいてほしいです。だからそういう意味において、紙ベースですけれども、書ける情報というのは、私はやはり書いておいていただきたいと思うのですけれども、その辺についてはいかがでしょうか。","respondent":"小林商業・ものづくり課長","answer":"記載内容につきましてはより中身について、先ほど申し上げたような４冊ですとかそういうところも含めて、次回またこのようなご説明、あるいは別の事業につきましても気をつけてまいりたいと考えております。もう一点、他自治体の例で大きいプレミアム率もあるのではないかです。","voiceIndex":30,"id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"そこの辺をしっかり押さえておかないと、ほかの自治体は高い、何で品川区は２０％なのかと聞かれたときに、私たちも議員ですから、聞かれたときにちゃんとした話を地域に持っていかないといけないわけです。だから、その辺についてしっかり教えてくださいと質問しているので、その財源というのではなくて、品川区商店街連合会から来ているリクエストが２０％程度と言われているのですね。","respondent":"小林商業・ものづくり課長","answer":"でも効果は上げていくという、非常にバランスも考えながらやっていくという中で今回２０％としているところでございまして、そういうところでまた経済状況が変わる部分はありますけれども、関係事業者なり。","voiceIndex":32,"id":"exchange-016"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"１点お聞きしたいのが、こうした国・都からの交付金ですけれども、様々使えるメニューがあったりもする中で、今回プレミアム付区内共通商品券事業とキャッシュレス決済ポイント還元を選んだというよりは、これが決まるときというのは、所管課からメニューの候補を出すのですか。","respondent":"小林商業・ものづくり課長","answer":"交付金の考え方という部分です。","voiceIndex":34,"id":"exchange-017"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうすると、幾つか挙げた中でこれと選ぶのか、それとも今回はメニューがある中でプレミアム付区内共通商品券事業とキャッシュレス決済ポイント還元事業かなとこの２つを挙げたのか、幾つかある中から候補を課として挙げる中でこれに決まったのかというのを伺いたいのと、あと、消費支出が落ち込んでいて消費喚起をというところでは。","respondent":"小林商業・ものづくり課長","answer":"実際に直接の支出、区民の方の収入に何かしらプラスになるという部分につきましては、区のいろいろな政策の中で総合的に対応すべき観点かなと考えておりまして、我々商業・ものづくり課としては、やはり先ほど申し上げたような区民生活と区内経済、具体的に言うと商店街とか店舗。","voiceIndex":36,"id":"exchange-018"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"この限られた交付金をどう使おうかというところでは分かるのですけれども、大本を転換させていかないと、先ほども言いましたけれども、消費税減税や賃金アップ、やはりこういうことを抜本的に進めていかないことには、この目的である消費喚起というのはなかなか進まないと思いますので、ここを区としても積極的に国に求めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2978#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":23907,"voices":48}},{"id":"r05-20231227-7","meetingId":"r05-cm12","date":"2023年12月27日","dateIso":"2023-12-27","committee":"厚生委員会","time":"午前１０時０７分～午前１０時５９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第１０４号議案、専決処分の承認を求めること","agenda":"第１０４号議案、専決処分の承認を求めること","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"６番の申請方法のところのイということは、今のご説明だと、新たに転入した方がイに当たるということで考えていいのでしょうか。なので、新たに転入されたという方でいいのかということの確認をしたいということが、１点です。相談窓口です。旧リボン（第３庁舎２階）で相談受付を行うということです。併せて庁内の３４２会議室のコールセンターの体制についてもお聞かせいただきたいと思います。","respondent":"豊嶋生活福祉課長","answer":"基本的には３万円の給付金をもらった方は、自動的に７万円を振り込めるはずなので、今回については、特に原則お手続は不要なのですが、こちらから振り込みますという通知だけは行きますので、これは何かと聞かれたときに対応ができるというようなことで、今。","voiceIndex":6,"id":"exchange-001"},{"speaker":"鈴木委員","kind":"提案","question":"もう一つ、たしか３万円のときは、住民税均等割は、これから新たに提案のところで均等割まで拡大されるということは、国のほうからも方針が出て、拡大されるということの提案があると思うのですけれども、家計急変世帯というものも、区独自にされたと思います。多分３万円のときは、家計急変世帯も対象にしましたよね。そこのところは検討をされたのか。その点についてお聞かせください。","respondent":"豊嶋生活福祉課長","answer":"よって、今回、家計急変の世帯については、次年度の国の方針を待って対応をしていくということで、今、検討をしています。","voiceIndex":8,"id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問","question":"次年度というのは、令和６年度ということですか。家計急変世帯まで３万円のところの対象にしたということは、多分、区独自で一般財源でやったと思うのです。インボイスも１０月からされましたし、そのような点では、今年度、今回の１０万円というところで、家計急変世帯というものも本当に対象にすべきではないかなと思うのです。検討をされた結果、どうだったのか。","respondent":"豊嶋生活福祉課長","answer":"ただ、先ほどの話ではありませんが、修正申告などをした方であれば、そこについては、対象であれば７万円の給付の振込をすることは可能ですので、まずはそちらの給付を迅速に一日も早くできるように進めようということで、現在、準備を進めているです。","voiceIndex":10,"id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"３分の１に減ったとはいえ、３万円のときも区独自にされたわけなので、ぜひそれはやっていただきたい。これからも、もしこういうことがあったとしたら、区としては、一番に区民のそのような切実な実態を直接つかめるところでもありますので、そのような実態もつかんでいただいて、対象を本当に困っている人のところに届くような形で、ぜひご検討をいただけたらということで要望をしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-004"},{"speaker":"こんの委員","kind":"質問・要望","question":"スケジュールがもう出ているので、あれなのですが、できる限り、可能な限り早く支給していただきたいという思いで、何点か質問をしたいと思います。私たちのところにも、「いつになったら振り込まれるのでしょうか」というようなお問合せは結構いただいております。専決処分をしてですが、この時期に支給といったところをもう少しご説明いただけますでしょうか。そこら辺のところを教えてください。","respondent":"豊嶋生活福祉課長","answer":"もちろん幾つかの業者に話は聞いていますが、皆さん同じなのです。結局いち早くラインを抑えるために、やはりいち早く我々も動きたかったということで、業者のほうにかなり無理を言いまして、それでも１月末にはなってしまいますが、今、何とかこれで準備を進めているです。","voiceIndex":14,"id":"exchange-005"},{"speaker":"こんの委員","kind":"確認","question":"全国でというか、全自治体で、これを進めていくので、東京都内だけでも、この年末年始、そのような印刷業者が大変にされているということは、想像がつくところです。もう１点は、受給承諾書、確認書の通知をされて、支給開始が下旬、末日だと、先ほどご説明がありましたけれども、この返事は返ってきて、初めて支給をするという形になると思うのです。そこら辺のスケジュール感を教えてください。","respondent":"豊嶋生活福祉課長","answer":"申請不要の方にお送りする受給承諾書からご説明いたします。通知自体の発送は、現在、どちらの通知も１月２２日を予定しております。この通知の発送後、およそ２週間の間隔、スパンをもって振り込むことが、国から令和３年の事務連絡で、各自治体に申し伝えがありました。","voiceIndex":16,"id":"exchange-006"},{"speaker":"こんの委員","kind":"質問","question":"ということは、受給承諾書のほうは、主に生活保護を受けていらっしゃる方や非課税世帯の方で、前回３万円をもう既に振り込んで、口座が分かっている人、いわゆる振込先が分かっている人たちがほとんどであるといった方たちが、１月末あるいは２月に入ってからになってしまうというような理解でいいのですか。もう一度、そこを教えてください。","respondent":"豊嶋生活福祉課長","answer":"そのとおりです。以前に振り込んだ口座がある方には、実際の着金は２月に入ってからという形になります。","voiceIndex":18,"id":"exchange-007"},{"speaker":"こんの委員","kind":"確認","question":"なるほど。そうですか。確認証のほうは転入された方で、行政のほうで非課税世帯だと把握ができない方が申請をして、申請とともに、申請書が届き次第、処理ができれば、どんどん支給ができるということなのですね。そうですか。できる限りそこをすごく早く支給ができたらといったところを思うわけなのですが、これは、再度確認をしますが、受給承諾書の支給を早めるということは、なかなか難しいのですか。","respondent":"豊嶋生活福祉課長","answer":"これも、実は、１月２２日は実現不可能だったのですけれども、何とかお願いをして、ここまで早めてもらったということと、やはり郵便局が年末年始は年賀状の発送の問題で、一度に大量に送れないということもありますので、郵便局とも調整をして、この日以降。","voiceIndex":20,"id":"exchange-008"},{"speaker":"こんの委員","kind":"質問・要望","question":"やはりこの年末年始は、非課税世帯の方や生活保護の方はお正月を迎えたいという思いでいらっしゃったお気持ちはよくよく分かるのですが、国が決まってからのスタートで、どこも一斉に始めていることなので、その中できる限りこのようにご努力をしてくださっていることはよく分かりましたので、あとはこのスケジュールどおり、スムーズに進めるようにお願いしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-009"}]},{"id":"topic-02","title":"第１０３号議案、令和５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第１０３号議案、令和５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"福祉タクシー等助成券交付対象者のほうを伺います。これと同じことが、１年前にもされたと思うのですけれども、そのときの対象者は４,５００人だったのですが、今回４,３００人ということは、福祉タクシー券の交付をされている方が２００人減ってしまったということなのでしょうか。そこのところの原因を一つ教えていただきたいことが１点です。６,０００円の考え方についても伺いたいと思います。","respondent":"松山障害者支援課長","answer":"今回につきましては、今回の見込みを出す際に、令和６年の１月１日の発送予定の見込み者として出したものは、現時点での交付対象者としては４,１９１人ということで、タクシー券につきましては３,５００人程度、自動車燃料費券につきましては８００人程度を見込んで。","voiceIndex":38,"id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問・要望","question":"４,２６５人が対象で、４,１０９人というのはタクシー券をもらっている人には、そのまま自動的に送るというやり方をされているのかということを伺いたい。今、品川区の福祉タクシー券は年間３,５００円だと思うのですけれども、それは、２３区の中でも、ちょうど真ん中ぐらいだった。その点についてはいかがでしょうかということも、お伺いさせていただきたいと思います。","respondent":"松山障害者支援課長","answer":"実際、昨年度タクシーが値上がったということもあるのですが、やはり、もともと燃料費の高騰が続いているということが、今回の大きなことですので、今後とも物価上昇や燃料費の状況を見ながら、区としては考えていきたいと考えています。","voiceIndex":40,"id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問・要望","question":"こういう区内商品券を６,０００円ということは、これはこれで評価するものですけれども、さらに、ぜひタクシー券そのものの引上げをしていただきたいということで、これは要望をさせていただきたいと思います。その点を１点、お伺いしたい。そこのところの差はないのかどうかというところを伺いたいと思います。その点についても確認をさせてください。","respondent":"豊嶋生活福祉課長","answer":"委員おっしゃるように、この３０世帯は、転入をしてきた方が、恐らくこれぐらいではなかろうかということで、まずは想定値として出したものです。","voiceIndex":42,"id":"exchange-012"},{"speaker":"鈴木委員","kind":"質問","question":"それであれば、気づかずに申請がされなくて、本来であれば、受け取れる方が受け取れていないということは、それほど考えなくていいのか、そこのところについては、どのような状況になっているのかも伺いたいと思います。","respondent":"豊嶋生活福祉課長","answer":"前回の３万円の給付金もそうですが、今回も、ある一定期間がたって申請がない方には、全てに勧奨通知をお送りします。前回も勧奨通知をお送りしております。なので、今回もそこでまだ申請されていませんということは、こちらからご通知は申し上げる予定です。","voiceIndex":44,"id":"exchange-013"},{"speaker":"鈴木委員","kind":"意見","question":"対象者なのに申請がされていないために、受け取れないということがないというところでは、ぜひこれからもくれぐれもよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-014"},{"speaker":"ひがし委員","kind":"質問","question":"今のことに続いてです。申請をされていない方に通知を送ると言っていたのですけれども、その後の追加の調査はしないのかという話です。視察へ行ったところなどでも、その追跡調査をして、送れない、申請をできない理由というところを把握するということが大切だったというところで、その申請をできなかった理由についての追跡の調査はされているのかを教えてください。","respondent":"豊嶋生活福祉課長","answer":"あくまで勧奨通知をお送りして、ホームページや広報しながわ、掲示板も含めて、先ほどの在宅介護支援センター、各種もろもろのところで、手を差し伸べて、申請をしていただくという方法を取ったのみですので、委員おっしゃるような追跡調査をしたかと言われたら。","voiceIndex":48,"id":"exchange-015"},{"speaker":"ひがし委員","kind":"質問・要望","question":"こちらは、要望です。もう１点は、福祉タクシー等助成券交付対象者への物価高騰対策支援について、そもそものところで、ご質問をします。こちらは福祉タクシー利用券または自動車燃料費助成券についての価格上昇分の助成を行うということで、もともと利用をしているタクシー券等ではなく、区内商品券にした意味というところを確認させていただきたいのです。その点についてお聞かせください。","respondent":"松山障害者支援課長","answer":"共通商品券についてのご質問です。前回と今回は同様なのですが、やはり年度内の執行は実際に困難でして、印刷が間に合わないということがありますので、年度内にお届けするためにはということで、共通商品券で相当分として対応をするものです。","voiceIndex":50,"id":"exchange-016"},{"speaker":"ひがし委員","kind":"質問","question":"区内共通商品券は、タクシーは一部しか利用できないという話もあったりして、タクシー券として使いたかった方にとっては利用しづらかったりするのか。その分を商品券として別のところでというところで、変えたところに対してお声はあるのかと思うのですけれども、実際の利用されている方々の反応がありましたら、教えてください。","respondent":"松山障害者支援課長","answer":"ただし、やはり区内共通商品券は、一部の福祉タクシーの事業者で、タクシー利用券としての使用を想定しているもので、全てのタクシー事業者に使えるわけではないのですが、ただ物価高騰という趣旨を鑑みますと、例えば家計への負担ということも大きいことですから。","voiceIndex":52,"id":"exchange-017"},{"speaker":"ひがし委員","kind":"質問・要望","question":"やはり必要なものと使いやすいものというところを、前回もこうだったからというところではなく、前回やったのであれば、その反応やご意見というところをいただいて、次に生かしていくべきだと思います。次回もし同じようなことになることが想定されるのであれば、ぜひ調査というものをして、利用しやすいものというところを発行していただきたいと思いますので、要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-018"},{"speaker":"こんの委員","kind":"質問・要望","question":"もう一つ言えば、今回私ども公明党としても、緊急要望をさせていただいた中に、「国の対象外の方にも、ぜひ支給を」という要望をさせていただいたものが、このように春のときに３万円支給、均等割といったところをしていただいたことは、大変評価をしております。いわゆるこの７万円を支給される方は、先ほどの話とまた確認が同じなのですが、支給までの流れを確認したいのです。その辺を教えてください。","respondent":"豊嶋生活福祉課長","answer":"２週間のお話です。","voiceIndex":56,"id":"exchange-019"},{"speaker":"こんの委員","kind":"質問","question":"一定期間というのは、おおむね２週間を待って、その一定の待機期間を待ってということは、受給承諾書を送った後、返事が返ってくるかどうかのおおむね２週間を待って、あともう少し様子を見て、振り込んでいくという理解でいいですか。","respondent":"豊嶋生活福祉課長","answer":"発送してから２週間たったら、もうその段階で支給の準備はできていますので、会計管理室を通して、決済を行っていくという流れです。","voiceIndex":58,"id":"exchange-020"},{"speaker":"こんの委員","kind":"確認","question":"すみません、再度確認ですが、そうすると、３月中に支給開始となっているものは、受給承諾書の方に限っては、３月を待たずして……。２月の下旬に送って、２週間を待つから、結局３月ということですね。分かりました。いずれにしても、この２週間を待って、その方たちから何らかのアクションがなくても、振込を開始するという理解でいいということですね。","respondent":"豊嶋生活福祉課長","answer":"原則、申請不要ですので、申請漏れがないというやり方で、３万円のときから始めているものです。","voiceIndex":60,"id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3680#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":16117,"voices":75}},{"id":"r05-20231227-9","meetingId":"r05-cm12","date":"2023年12月27日","dateIso":"2023-12-27","committee":"文教委員会","time":"午前１０時０７分～午前１０時４７分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第１０３号議案 令和５年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第１０３号議案 令和５年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"この２つの給付金を含む、今回、文教委員会所管分の補正予算３つの事業のうち、区の一般財源でお金を受領というのはあるのでしょうか。それぞれ財源を伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"区独自のひとり親世帯の臨時特別給付金につきましては、委員がおっしゃいます地方創生臨時交付金も使うということで、予定では１億１,４００万円ほど、地方創生の臨時交付金から使います。","voiceIndex":6,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"給付金のほうでまず伺いたいのですが、子育て世帯生活支援特別給付金ということです。これ、コールセンターとあるのですけれども、開設時期は何日間ぐらいでしょうか。それと、ひとり親世帯臨時特別給付金のほうですが、資料の裏面にスケジュールで「要申請者受付開始」とありますけれども、この要申請者とはどういう方なのか伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"コールセンターのほうですが、委員おっしゃるとおり、現在も国の給付金の関係でコールセンターをやっておりますが、そのまま引き続きコールセンターを設置しまして、今のところ、ほかの国の給付がなければ、５月末までというふうに考えているところです。","voiceIndex":8,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"申請が必要な方については、自分が申請が必要で、対象になっているかは、なかなか分かりづらいと思うのですけれども、やはり漏れがないように、ホームページと広報紙のみでは、少し周知としては不十分だと思いますので、周知を徹底していただきたいと思うのですけれども、いかがでしょうかということです。伺います。","respondent":"飛田子育て応援課長","answer":"ひとり親世帯のほうでの周知ですが、一応、住基台帳で対象世帯の方の情報を得まして、対象者へは案内を全員に送る予定です。なおかつ、案内漏れということがないように、まずは対象者全員に送付すると考えております。もう１つ、フードパントリーのほうです。","voiceIndex":10,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"私たちとしては、要望してきたのが、例えば、区内全ての児童・生徒の学校給食の無償化へ、国立私立等に通う子どもへの対象拡大ですとか、あるいは、区独自の大学生等への給付型奨学金を実施するですとか、これは所管が違うのですけれども、１８歳までの子どもの国保料を無料化するですとか、こういったことを今こそ実施に踏み出すよう求めたいと思うのですが、ここでは１点だけ。","respondent":"飛田子育て応援課長","answer":"今、国、各自治体でも様々な支援をしているところですが、今また東京都のほうにも、都立大学の無償化とか、そういうことも言って、大学に対しての奨学制度、大きく今、変化があるところですので、私としては、国また都の状況を見ながら、状況は注視していきたいと考えております。","voiceIndex":12,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"都立大はごく一部ですし、変化を見ているのではなく、やはり区内からも、区民の大学生から、何度か文教委員会にも請願・陳情など上がっておりました。そういった声を受け止めて、さらなる支援に踏み出していただきたいと、給付型の大学生への奨学金に踏み出していただきたいなと改めて要望させていただいて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"二、三件だったら、所管のところで対応できるのではないのかなと思ってしまうのですけれども、その辺のコールセンターの在り方について、どのように考えているのか教えていただきたいのと、このシステム作業支援委託というのがどのような事業なのかお知らせいただきたいと思います。以上、３つ教えてください。","respondent":"飛田子育て応援課長","answer":"ですので、それを１つ１つ職員が対応するというのはとても難しいことかなというふうには考えておりますので、やはりコールセンターの設置は必要かと考えております。そしてもう１つ、システム作業支援委託費です。","voiceIndex":16,"id":"exchange-006"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"もちろんやっていただいている方たちへの支援は、引き続き継続的にやっていただきたいですけれども、もうそろそろ子ども食堂をやらなくていい社会に向けた子育て支援を真剣に考えていただきたいと思うので、今回のこの件については、もう全然やっていただいてありがたいなと思うのですけれども、そういう根底の部分のところの問題解決に向けて真剣に考えていただきたいなと思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-007"},{"speaker":"高橋（し）委員","kind":"質問","question":"そこで、先ほども少し石田しんご委員から質問があったのですけれども、子ども食堂の今後の方向性というようなお話をしていただいたのですけれども、先ほど、フードパントリーの補助金が既にもう足りないということが１つあって、だから、ここで支給する。逆に言うと、フードパントリーだから、食品以外は使えないという仕組みなのかというところをお尋ねします。","respondent":"飛田子育て応援課長","answer":"今回、この商品券、きちんとチェックとかがどうなっているのかということですが、今回、実際に商品券の購入費としましては４３２万円を予定しておりまして、そのほかに事務費ということで４８万円上げします。","voiceIndex":20,"id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"意見","question":"それぞれ区のほうでも、今までの補助プラスで、ガバメントクラウドファンディングができたらしていこうというような意向を持っているということが分かりました。やはり現状ではなかなか厳しい。今の最後の商品券の使い道については、いろいろ制限がありつつも、柔軟に対応はできるという表現でよろしいのかなと思いますので、子ども食堂のほうには、そういうふうに伝えていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-009"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"私からは、私、生活保護の仕組みとかに詳しくないのですけれども、この子育て世帯生活支援特別給付金が、所得に計算されるのかどうか、その辺について伺いたいと思います。すみません、その点を１点教えていただきたいと思います。それをフードパントリーに特化したような形に見えるのですけれども、その辺についてはいかがなのでしょうか。","respondent":"飛田子育て応援課長","answer":"こちらですが、基本的には、やはりフードパントリーの利用者は全然減っていないというところもありますので、そこのところで、基本的にはフードパントリーに使っていただくということで、ただ、やはり各子ども食堂のやり方がありますので。","voiceIndex":24,"id":"exchange-010"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"子育て世帯生活支援特別給付金のほうは承知いたしました。特にこれによって生活保護の制度上、不利益な扱いにはならないという確認でよろしいですね。フードパントリーのほうです。その点について、もし何か見解があったら伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"今回は、あくまでもメインはフードパントリーというふうに考えております。ただ、どうしてもやはり運営上、必要なものはあると思いますので、それについては、まず相談していただいて、それで判断することは考えています。","voiceIndex":26,"id":"exchange-011"},{"speaker":"安藤委員","kind":"確認","question":"すみません、確認なのですが、１番の、基本的にこれ、国の給付金ではないですか。確認だけさせてください。","respondent":"飛田子育て応援課長","answer":"基本的に国の制度なので、収入認定はないというふうに言われています。","voiceIndex":29,"id":"exchange-012"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"子育て世帯生活支援特別給付金と、ひとり親世帯臨時特別給付金については、どちらも公明党が１２月５日に区長に緊急要望した内容が早急に反映された内容であり、非常に歓迎したい内容だと感じています。給付については、住基台帳に基づいて行われると先ほどもありましたが、今後のためにも、要申請者の確実な把握と周知の徹底を重ねて要望したいと思います。公明党は賛成です。公明党は賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"賛成です。深刻な物価高騰や子育て世帯の生活状況等に照らして、さらに一歩踏み込んで実施していただきたいという点はあるものの、今回の内容はどれも大切な事業でありますので、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"両方とも賛成です。１つだけ。臨時交付金が来て、こういう形でやっていただいて、大変すばらしいし、区の独自財源も使ってプラスしているのですけれども、臨時交付金とかがなくなった後に、その後、区としてどういうふうに子育てを支援していくかというところは、しっかりと検討していただきたいというふうに思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5118#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":13038,"voices":45}},{"id":"r05-20231227-5","meetingId":"r05-cm12","date":"2023年12月27日","dateIso":"2023-12-27","committee":"総務委員会","time":"午前１１時３０分～午前１１時５９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第１０３号議案、令和５年度品川区一般会計補正予算","agenda":"第１０３号議案、令和５年度品川区一般会計補正予算","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"１点、ひとり親世帯臨時特別給付事業についてですけれども、まず、補正全体としては、物価高騰が続く中、区民の暮らしを応援するものだと考えています。ただ、暮らしの実態は一層厳しいし、先行きの見通しも立ちませんから、適時こういう補正を組んで引き続き暮らしを応援してほしいし、来年度の予算についても、こういう姿勢で取り組んでいただきたいと、これは要望しておきたいと思います。","respondent":"遠藤財政課長","answer":"所得制限の考え方ですが、こちらは、今回、国の事業の中で所得の制限を設けて実施されているところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"だけれども、ここが苦しいから所得制限をなくすという考え方を今後も続けていくのか、拡大していくのか、改めて伺いたいと思います。私は、いずれにしても、生活が苦しい、そういう実態があるところは、十分に支援を行き届かせる必要があると思うし、子育て支援だったり、社会保障だったり、教育だったり、対象は全ての子どもたちやお年寄りを対象にすべきだと思いますけれども、最後にいかがでしょうか。","respondent":"遠藤財政課長","answer":"ここだったらいいとか、ここだったら駄目だとかという部分で、本当に困っている、困っていないという点は確かにあるだろうとは考えるところですけれども、ただ、今回については、ひとり親世帯の所得については撤廃した。","voiceIndex":7,"id":"exchange-002"},{"speaker":"松本委員","kind":"質問・要望","question":"総務委員会なので、本当に簡単に伺います。お願いします。","respondent":"遠藤財政課長","answer":"キャッシュレス決済ポイント還元事業ですけれども、こちらはどうしても事業者との調整が必要になりまして、おおむね６か月から７か月ぐらい実施にかかるというところで、４月、当初予算でやると遅くなってしまうため、今回、債務負担行為という形でやらせていただくところです。","voiceIndex":10,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"先ほど、中塚委員からもありましたけれども、物価高騰の影響は、様々な所得、生活している方たちに影響を与えていると思います。こういうこともやっている。それともう１点、フードパントリーというものが今回出ていますけれども、子ども未来応援事業、これはフードバンクとどのような違いがあるのですか。ここで増えていくわけですよね。その説明だけ分かる範囲で教えてください。","respondent":"遠藤財政課長","answer":"そちらにつきましては、以前、しながわ活力応援給付金などもやらせていただいておりますので、今後ですけれども、いろいろな社会事情等もあろうかと思いますので、そこら辺につきましては、臨機応変に対応させていただければと考えています。","voiceIndex":14,"id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"フードパントリーのほうは、そんなに変わらないのであれば、わざわざこういうふうにつくる必要が、子育て応援ということですから、どうなのかなと少し疑問に思います。これ、皆さんが生活をしているときに、皆さんの生活を支えているのは私はスーパーだと思うのです。そういうことを考えると、やはり共通商品券の在り方も、今後、何か考えていただきたい。意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"なぜ遅いのですかということをまず聞きたい。それで無償化になる。そういう話にきちんと我々が対応できるようにしないと、何でもかんでも物価高騰対策だ、低所得者対策だ、子育て支援策だと言って、何でもやるのは、少し違うような気がしてならなくて、特にここで臨時会まで開いて補正予算をやるわけだから、そこら辺をもう少し丁寧に説明してほしいと思うのだけれども、そこら辺の考え方だけ教えてほしい。","respondent":"遠藤財政課長","answer":"様々な意見が当然あろうかと考えていますので、本当は全てかなえられればいいのかなというふうに思っているところですけれども、優先順位をどうしてそういうふうにつけたのかというところは、なかなかすぐにパッとご納得いただける説明は。","voiceIndex":18,"id":"exchange-006"},{"speaker":"塚本副委員長","kind":"確認","question":"確認ですけれども、例えば、子育て世帯生活支援特別給付とか、住民税均等割のみ世帯、これは、今は財調を取り崩して歳入に当てていますけれども、いずれは国のほうから財源として当て込まれる、そういうふうに認識しているのですが、そういったときに、これは３月３１日の年度内に使い切らないと、給付し切らないといけないというような縛りとかがあるということで。","respondent":"遠藤財政課長","answer":"こちら２つの事業については、一応、年度内を目標にしているところではありますが、これはシステム改修なども出てくる形なので、国からは、一定、繰り越しても大丈夫というような話もいただいているところですので、できるだけ年度内にやらせていただいて、万が一難しい場合には。","voiceIndex":22,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問・要望","question":"１点だけ。別の方もお聞きしていたのですが、プレミアム付区内共通商品券ですが、これを区外の方も購入できるという話を聞いたのです。でも、基本的に区の予算を充当するということならば、残る、残らないはあるかもしれないですけれども、私はやはり区民に何とかして買っていただくような仕組みにするよう、区のほうでもしっかり取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"だから、意見だけ。質問ではなくて、それだけは今指摘しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2286#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":10577,"voices":40}},{"id":"r05-20231227-10","meetingId":"r05-cm12","date":"2023年12月27日","dateIso":"2023-12-27","committee":"議会運営委員会","time":"午後 ２時３０分～午後 ２時３２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5532#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":1094,"voices":8}}]);
